-- Resolução comentada (explanation) das questões do ENEM 2025 inseridas na
-- V11, que entraram sem explanation.
--
-- Cada resolução justifica a alternativa do gabarito oficial do Inep e, quando
-- ajuda o estudante, aponta por que as demais não servem. Fórmulas seguem a
-- convenção da V11: índices e expoentes em Unicode e frações na forma a/b.
--
-- A questão é localizada pelo SHA-256 do enunciado gravado pela V11, como na
-- V12, porque os ids variam entre bancos. Só recebe explanation a questão que
-- ainda está sem uma (nula ou em branco): resolução já cadastrada pela API não
-- é sobrescrita, e questão cujo enunciado foi alterado depois da V11 não é
-- tocada.
CREATE TEMPORARY TABLE enem_2025_explanation (
  `stage` varchar(40) NOT NULL,
  `statement_sha256` char(64) NOT NULL,
  `explanation` text NOT NULL,
  PRIMARY KEY (`stage`, `statement_sha256`)
);

INSERT INTO enem_2025_explanation (stage, statement_sha256, explanation) VALUES
    -- 1º Dia, 01 inglês. Gabarito: E.
    ('1º Dia', '1a9525b11a1f892901ece9b7e26a84a76464d21299a43c6bb471f6dedb8c816e', 'O texto chama de “snowflake generation” os universitários “so delicate they can’t handle controversial ideas”, ou seja, jovens frágeis diante de ideias contrárias e de frustrações, e atribui essa fragilidade a uma cultura que repete às crianças que elas são especiais. A expressão aponta, portanto, posturas de uma juventude avessa a contrariedades (E). Não se trata de obstáculos impostos aos estudantes (A) nem de conflitos no ambiente universitário (D), e as mensagens de incentivo são criticadas, não destacadas (B).'),
    -- 1º Dia, 03 inglês. Gabarito: D.
    ('1º Dia', 'fadeb812fce81bb254b694fddfe60fc88bf06ef4909d8d25e20b8ee7a7de347d', 'Glory Ames se frustra com fantasias como “pow wow princess” vendidas no Halloween e afirma: “They blatantly take certain aspects of our culture, race, religion, and use it for their advantage and ignore the people living it”. O texto critica, portanto, a apropriação cultural, isto é, a exploração indevida de elementos da identidade indígena (D). A foto da menina com uma bala na testa é um exemplo dessa ofensa, não uma denúncia de violência contra crianças (A), e o texto não valoriza as vestimentas (C) nem propõe ações de combate ao preconceito (E).'),
    -- 1º Dia, 04 inglês. Gabarito: D.
    ('1º Dia', 'ae1851092bc9a637799db54601288967d8cf989667792df6eb7129aeb3de2448', 'Angela Davis afirma que a filosofia só merece esse nome se for relevante para os problemas humanos e ajudar a erradicar a miséria, e que hoje o “proper living” de Sócrates significa libertar-se da pobreza, da necessidade econômica e da opressão mental. Ela aproxima a filosofia dos problemas sociais (D). Davis não a critica (A) nem a restringe à academia (B), apoia-se em Sócrates em vez de se afastar dele (C) e não a culpa pela pobreza (E).'),
    -- 1º Dia, 05 inglês. Gabarito: D.
    ('1º Dia', '235e7d8a284d17263a7edb5913167ab128c0f79320753085f9c75c05f47704cc', 'O eu lírico pede que se lembre da terra “whose skin you are”, afirma “we are earth”, reconhece que plantas e animais também têm “tribes, families, histories” e conclui “you are this universe and this universe is you”. O poema ressalta a integração entre seres humanos e natureza (D). Os astros (A) e a origem dos seres (B) aparecem só como parte desse todo, e a “earth” é a Terra como elemento natural, não a terra natal (C).'),
    -- 1º Dia, 02 espanhol. Gabarito: C.
    ('1º Dia', '0070f1002228fda0b490fd90f63bf32cd91ec1a77d6c460547b7ea690ec39dd5', 'Ver o mundo “a través de una pantalla” significa vê-lo por meio de uma tela. O texto acrescenta que hoje as gerações se definem pelo uso de determinada tecnologia e que muitos aspectos do mundo analógico serão alheios aos Alfa, o que evidencia a dependência de recursos digitais (C). Não há conflito entre idades (A) nem efemeridade da tecnologia (B), e a menção aos fatos históricos só explica como as gerações eram definidas antes, sem indicar indiferença dos Alfa (E).'),
    -- 1º Dia, 03 espanhol. Gabarito: B.
    ('1º Dia', '056d29f4e05fff1fe60836f3937d2279a0f885b25bbf11a0b687e2fa85b62506', 'O eu poético cobra do patrão “¿Dónde está nuestro pan?” e pergunta onde ele escondeu o dinheiro, enquanto os ricos exibem quadros de Tàpies e Antonio López e têm “muertos a sus espaldas”. A canção critica a postura dos patrões, que acumulam riqueza à custa dos direitos dos trabalhadores (B). Os artistas são citados como símbolo de ostentação, não de orgulho (A), o tom é de acusação e não de diálogo horizontal (D), e a letra não propõe soluções (C) nem trata da insalubridade (E).'),
    -- 1º Dia, 04 espanhol. Gabarito: A.
    ('1º Dia', '0e119680ab7e5ea569f99a95caf13502bebba7fcda73570831beed5c027168ca', 'O texto mostra que “guagua” chegou às Canárias trazida de Cuba por imigrantes que voltaram (com o sentido de ônibus) e que, no sul da América, vem do quíchua “wáwa” ou do mapuche (com o sentido de bebê). É a ideia do título: as palavras migram, o que evidencia a presença de empréstimo linguístico no espanhol (A). O pedido à Real Academia Española de incluir “guagüismo” é um detalhe, sem validação (B), e o texto não fala em concorrência (C), hierarquia (D) ou disputa entre povos (E).'),
    -- 1º Dia, 05 espanhol. Gabarito: D.
    ('1º Dia', 'da059451772aa98055de37c72889dd08e90601073962cbda6a6bd0682f2bcfaf', 'A letra é construída com verbos no pretérito imperfeito do indicativo: “era”, “quedaba”, “bastaba”, “alcanzaba”, “podía”, “iba”, “soñaba”. Esse tempo expressa ações habituais e contínuas no passado, típicas da evocação de lembranças da infância, o que caracteriza o texto como relato de memórias (D). Os diminutivos (A) marcam afeto, os termos da fauna e da flora (C) e da variedade caribenha (E) marcam a origem cubana e os adjetivos (B) descrevem, mas nenhum deles situa o relato como memória.'),
    -- 1º Dia, 06. Gabarito: C.
    ('1º Dia', '7eb954e8840dddc7bdaf45ed50ffb831390c9bef1668c5b7e55146ec65644792', 'A crônica parte de situações do cotidiano, muitas vezes vividas pelo próprio autor, para propor uma reflexão. A autora parte da própria experiência (a assinatura no banco, os bilhetes na geladeira, os post-its do escritório) para refletir sobre a escrita e suas tecnologias, o que caracteriza o gênero (C). A defesa de opinião sobre tema coletivo é própria do artigo de opinião (A), a exposição sobre tecnologias, do texto expositivo (B), e a ordem cronológica, da narrativa (E). A interlocução com o leitor (D) é pontual e não define o gênero.'),
    -- 1º Dia, 07. Gabarito: E.
    ('1º Dia', '7472224a6266a54b406904b9b629d9433259e70c4241800558722c63add425b9', 'A autora mostra que os bilhetes ocupam espaços específicos: na porta da geladeira, para falar com os coabitantes, e em post-its no escritório, para lembrar a si mesma de tarefas. Ela apresenta, portanto, a diversidade de usos do bilhete no cotidiano (E). Não há formalidade nessa comunicação (A), a ansiedade citada vem do fluxo de tarefas e não da velocidade da comunicação (B), a concisão é um hábito dela e não uma obrigação (C), e a escrita de próprio punho é valorizada, não questionada (D).'),
    -- 1º Dia, 08. Gabarito: E.
    ('1º Dia', 'a7dcca247917dbb423515d64fc3b33f34c88292ba50d60f7842181df6c47aee5', 'A opinião da autora é a de que as tecnologias de escrita convivem em vez de se substituírem (“nada dispensa nada”). Ela a sintetiza no fim ao trocar “Do punho ao pixel”, em que a preposição sugere a passagem de um meio para o outro, por “o punho e o pixel”, em que a conjunção aditiva expressa a coexistência dos dois (E). Os demais trechos (A, B, C, D) tratam de experiências pontuais da autora e não resumem a tese do texto.'),
    -- 1º Dia, 09. Gabarito: D.
    ('1º Dia', '9d0bac4aa251448e8961de67ec00c45ba39a7331723fc87f3b772e7f2dd723b0', 'A autora diz que suas mãos ainda tocam o teclado e as telas, “mas não expressam mais a minha letra. No lugar, aparecem Times New Roman, Arial, Calibri e mais uma centena de ‘letras’ à minha escolha”. As fontes tipográficas disponíveis ilustram a escrita digital, em oposição à letra manuscrita (D). As demais alternativas são genéricas: o uso de tecnologias diversas (A), novos recursos (B) e telas (C) também se aplicam à escrita manual ou não representam a “letra” digital, e a delimitação dos espaços (E) se refere aos bilhetes.'),
    -- 1º Dia, 10. Gabarito: C.
    ('1º Dia', 'ff76de56bf57162c590d0faa8a0d57bafc868be5b055f4af1e0ceb30e6722de4', 'No último parágrafo, a autora afirma que “nada dispensa nada”, que “não adianta muito pensar sempre como se tudo fosse excludente” e que o certo é “o punho e o pixel”. As novas tecnologias de escrita, portanto, coexistem com as já estabelecidas (C). O texto não as relaciona à facilidade (A) ou à agilidade (D); a desigualdade no acesso à escrita é mencionada, mas não é a conclusão (B), e a autora não diz que elas surgem só onde são necessárias (E).'),
    -- 1º Dia, 11. Gabarito: A.
    ('1º Dia', '7d4dcf879c4b9e10daf4058f6596ae3330e1bef9f6eaf72b527939efcf9642f7', 'A ex-jogadora afirma que, por trás do espetáculo e das mensagens de superação, o esporte não é tão inclusivo, critica “a ideia romântica que a mídia passa” e diz que tudo parece mais fácil “quando apenas as conquistas são mostradas”. Os meios de comunicação, portanto, invisibilizam as dificuldades do esporte (A). Ela não diz que o treino desestimula (B) nem que o esforço é desvalorizado (C), e incentivos financeiros (D) e rótulos a iniciantes (E) não são tratados.'),
    -- 1º Dia, 12. Gabarito: E.
    ('1º Dia', '202189e31545fd63e5abe588f28d88b1103dc1502ee52a2424aba56e80a22db2', 'As atletas destacam a saúde mental: Rebeca Andrade diz que “a minha briga está na minha cabeça”, Rayssa Leal exalta a terapia e a seleção feminina de futebol usa o suporte psicológico como reforço no treinamento. Elas defendem a importância da saúde emocional (E). O preparo psicológico complementa o físico em vez de subordiná-lo (B), Rebeca diz justamente que não se trata de vencer a adversária (C), e equipamentos (A) e expressão corporal (D) não são mencionados.'),
    -- 1º Dia, 13. Gabarito: B.
    ('1º Dia', '087ddd070fe4756b9944c89dde1ca64c4461b9efe45a6174d65ece43205b693f', 'A “língua de santo” tem aparente forma portuguesa, mas “repousa sobre sistemas lexicais de diferentes línguas africanas que provavelmente foram faladas no Brasil escravocrata”. Sua importância para o patrimônio linguístico está em conservar elementos dos falares dos escravizados (B). A carga mítica é uma característica dela, não a razão de seu valor patrimonial (A); a base é africana, não portuguesa (C); e ela pertence à nação do orixá, do vodum ou do inquice, e não a uma nação africana atual, o que afasta E.'),
    -- 1º Dia, 14. Gabarito: C.
    ('1º Dia', '21ba2fe47216ac7c98fd8ef7e1222d897b56049f91cdafd0338c35e361d6cd51', 'O narrador teme não só tirar zero na faculdade, mas também não conseguir emprego nem de faxineiro e, mesmo diplomado, ser olhado “de cara feia” por um policial e acabar preso. A obra, Contos negreiros, retrata a experiência de jovens negros e pobres, e a reiteração dos medos exprime incertezas centradas em sua condição social (C). Não houve fracasso escolar, apenas medo dele (B), a formação é só uma das preocupações (D), e o futuro familiar (A) e as políticas assistenciais (E) não são o centro do texto.'),
    -- 1º Dia, 16. Gabarito: E.
    ('1º Dia', '74b94ac586419262c6b890a969cb258bb7cbff7952b217984fd95f16d11c45ef', 'O Simbolismo trabalha com símbolos, sugestões e estados da alma. No soneto, cujo título é “Símbolos”, o eu lírico vê no mar e na rocha “a minha vida e a tua”: o “tu” é o mar dúbio, que tem “carinhos de amor e fúrias de demência”, e o “eu” é a rocha, a “dor empedernida”. Ele metaforiza o conflito amoroso nessas imagens (E). O eu lírico não rejeita as emoções (A), a dubiedade é do outro e não do olhar (B), o “eu” é imóvel e não volúvel (C), e a inconsciência é atribuída ao mar, não a si mesmo (D).'),
    -- 1º Dia, 17. Gabarito: C.
    ('1º Dia', 'd3182e835b0988f2163d49fb333e01ec9c0f31cba6ff2f9116e74710d5b58e41', 'A repetição de “antes” opõe a avó de antigamente (“antes da fome”, “antes do cansaço dos anos”) à avó do presente, marcada pelo Alzheimer, e culmina em “Eu era sua neta. Antes do Alzheimer chegar, eu era sua neta. Mas ela é e sempre será minha avó”. A locução ressalta fatos que ressignificam o momento presente (C). Os fatos não são simultâneos (A) nem uma sequência de ações consecutivas (D), e a locução não compara lembranças (B) nem as explica (E).'),
    -- 1º Dia, 18. Gabarito: B.
    ('1º Dia', '7d01c8d80d3fbc84e7e8c9055608316b2c067058b9ad65a71367395e62b0ce61', 'O pai descreve Nocência apenas por atributos físicos e de modos (“bonita”, “ariscazinha”) e conta que tratou de casá-la assim que ela “tomou corpo”, acertando o noivado com Manecão sem consultá-la, porque “os pais devem tomar isso a si”. É o ideal romântico da mulher como figura decorativa e passiva diante do protagonismo masculino (B). O ambiente rural não é apresentado como formador moral (A), a origem social do casal não é discutida (C), não há menção a dote (D) e a identidade da jovem não é envolta em mistério (E).'),
    -- 1º Dia, 19. Gabarito: C.
    ('1º Dia', 'e33eb7e7a9d1b6a9200f136ca754c36a2fedfebba107a15b2ff4a2e7c9b669aa', 'O programa Maré Inclusiva, lançado pelo Ministério do Esporte, busca ampliar as oportunidades de pessoas com deficiência praticarem o surf e, segundo a Secretaria Nacional do Paradesporto, “promover a inclusão por meio do parasurf”. O texto evidencia a importância de uma política pública esportiva para a inclusão (C). Ele trata só do Brasil (A), não fala de demandas paralímpicas (B) nem avalia a eficiência de iniciativas em megaeventos (D), e não há menção à falta de investimento (E).'),
    -- 1º Dia, 20. Gabarito: E.
    ('1º Dia', 'dc5d1c21b64780fe89db029fd8bf60473cc95a32d72a27734f46f3f121623cb2', 'O texto é um artigo de lei, gênero normativo que exige linguagem formal, impessoal e precisa para evitar ambiguidades e ter validade jurídica. O emprego da norma-padrão decorre, portanto, das características do gênero (E). A lei se dirige a toda a sociedade, e não a um público especializado (A), e o registro não depende da relevância do conteúdo (B, D) nem de circular em contextos pedagógicos (C).'),
    -- 1º Dia, 23. Gabarito: E.
    ('1º Dia', '5a0ac9419932a402083534e3fb3153cacc834a52071973fc0fdb9c75c6aff79f', 'Ruy Castro critica as expressões automatizadas usando-as em sequência: “proativo”, “novo normal”, “zona de conforto”, “ressignificada”, “empatia”, “lugar de fala”, “resiliência”, “fora da caixinha”, “cringe”. O acúmulo dos próprios clichês que são objeto da reflexão gera o humor que sustenta a crítica (E). A efemeridade dos usos é mencionada só no final (A); a primeira pessoa (B), o “simples assim” (C) e a interlocução com o leitor (D) aparecem, mas não são a estratégia central.'),
    -- 1º Dia, 27. Gabarito: A.
    ('1º Dia', 'b7c87315096cfb509df98517271959798a46e72d832669ebd1a3b5d729a4e8e6', 'O texto diferencia a briga, que “desumaniza o outro”, da luta, que considera as intenções e habilidades do adversário e é também um combate “consigo mesmo”, “contra as próprias limitações” e “contra o próprio orgulho”. A diferença está na superação pessoal presente na luta (A). A violência é atribuída à briga, não à luta (B); o texto não diz que a briga tem regras (C) nem que desenvolve habilidades (E); e o desafio destacado na luta é interno, não externo (D).'),
    -- 1º Dia, 28. Gabarito: B.
    ('1º Dia', 'a3e649f131c5217ad61086c99d4b06dfb1f93d40cbc3a9ec459e56de29a3825e', 'O eu lírico repete o apelo “Pequenino, acorda!” e pede que a criança morta recupere o alento e fuja “da cobiça dessas fundas valas”, como se ela apenas dormisse. A recusa em aceitar a irreversibilidade da morte intensifica o luto (B). A paisagem do cemitério (A) e a pontuação (C) reforçam o clima, mas não são o centro; o poema não evoca a religião como consolo (D), e o “dormindo” é eufemismo para a morte, não impressão de sonho na estrutura (E).'),
    -- 1º Dia, 29. Gabarito: A.
    ('1º Dia', '31530f176fc78632766b25420a438c53077cee5ab38b51f361e89d7d3adfb3f8', 'O narrador enumera os produtos da cana (açúcar, melado, rapadura, aguardente) ao lado de sobrados e senzalas e descreve um “reino” com reis, cortesãos e “muitos escravos”, em que a “corte do massapé” não deixa escapar “nenhum mísero grão” para quem é de fora e os nomes se repetem na mesma parentela. A riqueza da terra espelha a permanência dos privilégios de classe (A). O texto não traça um panorama da população do campo (B), não exalta a fartura (C) e não valoriza o trabalho coletivo (D) ou o trabalho ao longo das gerações (E): o que passa de geração em geração é o privilégio.'),
    -- 1º Dia, 31. Gabarito: E.
    ('1º Dia', 'cc9b61d90a1b108b62d5512f8c17a8500748c6a101e2f19d2d206318b666df7c', 'A autora abre o texto com as críticas a Margot Robbie, que não seria “bonita o suficiente” para ser Barbie, e a Paolla Oliveira, chamada de gorda. Se até mulheres tidas como padrão de beleza são fiscalizadas, nenhuma escapa, o que introduz a ideia de que a vigilância afeta todas (E). O comentário sobre a própria aparência (A) vem depois, como consequência dessa ideia; os parênteses (B) e o “reality show” (C) são recursos pontuais, e Naomi Wolf é citada mais adiante, sobre dietas (D).'),
    -- 1º Dia, 32. Gabarito: D.
    ('1º Dia', '324489b03e3bd6fe6891df6acee9c85447d43a5c3b68d8091663097354f19cf4', 'O “daí” funciona como marcador discursivo de sequência: o falante o repete para encadear os acontecimentos do filme enquanto organiza a fala em tempo real. É uma estratégia típica da linguagem oral espontânea (D). O uso é comum entre falantes de todas as regiões e níveis de escolaridade, então não revela a origem (B) nem a escolaridade (C) do locutor; também não resulta de adequação ao interlocutor (A) nem enfatiza partes do relato (E), apenas as liga.'),
    -- 1º Dia, 33. Gabarito: B.
    ('1º Dia', 'd36a549b21426c736c8100fb9cb81e5b4384afc2260a22657ab212f346162d92', 'O verbete traz o nome em wajãpi (Uruku), em português e em outras línguas e define a planta a partir da cosmologia Wajãpi: o urucum espanta os donos da água e das plantas e disfarça o cheiro humano diante dos espíritos. Ao registrar um termo com o sentido que ele tem na perspectiva ancestral indígena, contribui para preservar o patrimônio linguístico (B). Não descreve um rito medicinal específico (A), “Rocou” não é de língua indígena (C), não há atualização de saberes (D) e as propriedades descritas não são científicas (E).'),
    -- 1º Dia, 35. Gabarito: E.
    ('1º Dia', 'f6f3d7804edc1889603d638b8b019283b75c9489fcec04b57ddbde601bb0814b', 'O texto aponta que a página do jornal comporta várias matérias, o que impõe a cada uma “um número restrito de laudas” e obriga o cronista a explorar o espaço “da maneira mais econômica possível”, de onde nasce a riqueza estrutural da crônica. O aspecto tecnológico é a restrição espacial do suporte (E). A ideologia do veículo (A) e o público leitor (C) são limitações de ordem social, a densidade temática é traço do conto (B) e o texto nega que o gênero apresente uma moral (D).'),
    -- 1º Dia, 37. Gabarito: C.
    ('1º Dia', '834b2e6513c4200bf210f50dfbda9d713547faa23cbc24a476df35acde7e18a0', 'O texto mostra que o rádio resistiu à chegada da TV e foi incorporado à internet e aos dispositivos móveis, dando origem à web rádio e ao podcast; o pesquisador da UFU diz que ele “não se tornou obsoleto” e que o podcast é “uma evolução natural do rádio”. A reflexão é sobre a permanência do rádio e sua evolução pela tecnologia digital (C). O podcast é apresentado como continuação, e não como substituto do rádio (B), e o texto não trata do desenvolvimento da TV (A), de sua influência sobre o radiojornalismo (D) nem das interações humanas (E).'),
    -- 1º Dia, 38. Gabarito: A.
    ('1º Dia', 'cdfda1ed28bc97e3a81c88c85de7509440755fd313503bdba4327d356f44c211', 'O narrador descreve com ironia uma pensão em que a mãe calcula o namoro da filha com um rapaz que “não valia nada” e um coronel casado, com “tremor lúbrico nas banhas moles da face”, recebe visitas matinais da viúva sob o pretexto de ir à missa, enquanto os hóspedes “riam-se à socapa”. A ambiência é de escárnio sobre a degradação moral dos indivíduos, traço do Naturalismo (A). Não há descrição de insalubridade (B), os folhetins aparecem só como passatempo (C), a concessão rendosa é um detalhe (D) e o texto não discute escolaridade (E).'),
    -- 1º Dia, 40. Gabarito: A.
    ('1º Dia', '95d9813d2a18afa29f8e16b15d3fd9b72cd7ce7eebed690537b7a2919ea581d3', 'As passagens em “juridiquês” usam vocabulário rebuscado e latinismos que as tornam incompreensíveis para a maioria; traduzidas para a variedade padrão acessível ao público em geral, revelam conteúdos simples, o que expõe o exagero da linguagem jurídica e cria a ironia (A). A tradução não é coloquial (C) nem histórica (B), e as variedades erudita (D) e técnica (E) são justamente as do texto original.'),
    -- 1º Dia, 41. Gabarito: D.
    ('1º Dia', 'bdc7965446f63837543f95490ce2e1a10d71ae11dd764420199665e51e9830aa', 'A reportagem destaca que os Jenipapo-Kanindé “quebraram a tradição da sucessão masculina” ao escolher a Cacique Pequena, primeira cacique mulher do Ceará, que agora prepara duas filhas para sucedê-la. A função social está em dar visibilidade ao protagonismo feminino na linha sucessória desse povo (D). A tradição foi rompida, e não reforçada (B), e o número de famílias (A), o estudo antropológico (C) e o reconhecimento pela Funai (E) são informações de apoio.'),
    -- 1º Dia, 42. Gabarito: D.
    ('1º Dia', '5d0ea2a17f3da1a8d18bb385fcc4e7f27685c48bc82ed63d0e140b0c27fdfb1a', 'O texto enumera motivos para ler para crianças: cria laço emocional, ajuda no desenvolvimento cognitivo, “ensina sobre o mundo” e incentiva a imaginação. A persuasão se apoia nessa enumeração de razões (D). O “se” só introduz a lista (A), o “Parece que” relativiza a concorrência da tecnologia e não a opinião do autor (B), e a metáfora “laço de amorosidade” (C) e o “é nossa função” (E) são recursos pontuais.'),
    -- 1º Dia, 44. Gabarito: A.
    ('1º Dia', '53e7ab453700630bfc7600b20ebcf7b480399657409f097ac42b9b5f1076b303', 'O Texto II retoma o mito do Texto I no título, “Os Doze Trabalhos”, na enumeração dos muitos serviços de João (bombeiro, eletricista, pedreiro, jardineiro, caseiro, motorista) e no desfecho “Mas pode chamar de Hércules”. A intertextualidade com o mito é o recurso do Texto II (A). O Texto II não resume os fatos do mito (B), usa vocabulário do cotidiano (C), e os trabalhos de João são de sobrevivência, não de expiação (D). O Texto I está no presente, o que afasta E.'),
    -- 1º Dia, 45. Gabarito: B.
    ('1º Dia', 'fb6b35b2fb48fd28a5a9a58fe8be1b83c1a17268bcef7a7800721cb67577cd81', 'Em “qualquer detrito espacial que se aproximasse de nós seria identificado e rotulado, e sua trajetória calculada”, o possessivo “sua” retoma “qualquer detrito espacial” (B). A oração “que passou de raspão” se refere ao “outro asteroide” (A); “isso” retoma a ideia anterior, de que o meteoro “era pequeno demais” (C); “o que nos daria tempo” retoma a identificação antecipada dos detritos (D); e “o asteroide da Sibéria” retoma o meteoro já citado na primeira linha, sem introduzir elemento novo (E).'),
    -- 1º Dia, 46. Gabarito: A.
    ('1º Dia', '41264bad9bf46b43995d3f5fcdee856deca3c1b891367647f4c3727a905338de', 'O texto liga as idas de Virgínia à Feira de São Cristóvão, reduto nordestino no Rio de Janeiro, à Paraíba, que mais tarde seria a sua casa, e à lembrança da mãe costurando em casa cercada dos filhos. Os itinerários se associam à vida dos personagens por apresentarem histórias conectadas e recordações do lugar (A). O texto não trata de indústria ou direitos trabalhistas (B, D) nem de preconceito ou segregação (C, E).'),
    -- 1º Dia, 47. Gabarito: D.
    ('1º Dia', '28a30f8663d8b8be6a90bd4f8d24a3b799daec040ea20c46f2b38fe2e303f69e', 'A Reforma de 1881 (Lei Saraiva) instituiu a eleição direta, mas passou a exigir dos novos eleitores que soubessem ler e escrever, além de comprovar renda. Num país de maioria analfabeta, o eleitorado caiu de 13% da população livre para 0,8% da população total, e a Constituição de 1891 manteve a proibição do voto dos analfabetos. A variação se explica pela exigência da alfabetização (D). As mulheres já não votavam antes da reforma (A), os imigrantes não foram o alvo da mudança (B), a comprovação de domicílio não explica a queda (C) e o voto não era obrigatório (E).'),
    -- 1º Dia, 48. Gabarito: B.
    ('1º Dia', 'c7164668ac06f6650dd5860acc2ed706ff3a4035c1a8dbfc5f90ca0378f85c2e', 'O professor explica que a Floresta Amazônica é uma grande provedora de água para a atmosfera, por meio da evapotranspiração, e que o desmatamento reduz essa umidade e, com ela, as chuvas que abastecem os reservatórios das hidrelétricas. A dificuldade na geração de energia vem da alteração da paisagem em um local estratégico (B). O texto não trata de variáveis meteorológicas de pesquisa (A), de demandas industriais (C), de metas climáticas (D) ou de mudanças geológicas (E).'),
    -- 1º Dia, 49. Gabarito: D.
    ('1º Dia', '5e23e4cd6e8ff3f9287d9529e4b8e45b0eeb8bebb72d1683c21c4340478dc3c6', 'Segundo o texto, Adam Smith via o açougueiro e o padeiro não só como pessoas em busca de ganho financeiro, mas como pessoas “moralmente motivadas”, cuja moral se baseia na empatia e no julgamento, distinguindo “o que queremos fazer” do “que sentimos que devemos fazer”. O lucro aparece associado à percepção de responsabilidade ética (D). A satisfação subjetiva corresponde ao “que queremos fazer”, justamente o que a moral limita (B), e o texto não trata de poder político (A), monopólio (C) ou reconhecimento público (E).'),
    -- 1º Dia, 50. Gabarito: E.
    ('1º Dia', '90c2c374673d732a6d14e99eee205cd9a4e20b1974ec1d655c3d0670479c42f1', 'Aristóteles classifica os governos pelo número de governantes (um, poucos ou todos) e por sua finalidade: os que visam ao bem comum são justos, e os que servem a uma só parte são desvios. As três formas justas são a monarquia, a aristocracia e o governo de todos, chamado politeia e tradicionalmente identificado à democracia na teoria clássica (E). Tirania e oligarquia (A) são desvios da monarquia e da aristocracia, e as demais alternativas trazem formas que não pertencem a essa classificação (B, C, D).'),
    -- 1º Dia, 51. Gabarito: E.
    ('1º Dia', '45f134e6b26c1f4cb1cf08596f2fe8cccdb9ccfc26c35ed5e9c1ca0fdc34fb3e', 'A Grécia se opunha ao nome Macedônia, igual ao de uma de suas províncias, e por isso bloqueava as negociações de adesão do vizinho à União Europeia. Ao adotar o nome Macedônia do Norte, o país remove esse obstáculo e abre caminho para a integração regional (E). A mudança não envolve moeda (A) ou território (D), não protege a cultura local, já que é uma concessão à Grécia (B), e não tem relação com minorias étnicas (C).'),
    -- 1º Dia, 53. Gabarito: E.
    ('1º Dia', '9cb4f0718a011e447c586ed87fbfe2f7696dcea695336e263b8f34147ed54d53', 'Hume afirma que a eloquência em seu grau mais alto “deixa pouco lugar à razão ou à reflexão” e, dirigindo-se “à imaginação e aos afetos”, “subjuga” o entendimento dos ouvintes. Ele a restringe, portanto, ao âmbito da persuasão, de modo análogo à crítica de Platão aos sofistas, que buscavam convencer sem compromisso com a verdade (E). As alternativas que a ligam à objetividade do conhecimento (A), aos absolutos (B), à lógica (C) ou à racionalidade metódica (D) contrariam o texto, que a opõe à razão.'),
    -- 1º Dia, 54. Gabarito: C.
    ('1º Dia', '39f437324f0190ff7433c56b7510f64caa411e07bc200822c9dc3d22f2e5234d', 'Neutra na Primeira Guerra Mundial, a Espanha tinha imprensa livre e noticiou a epidemia, enquanto os países em guerra censuravam as informações vindas dos campos de batalha para não abalar o moral das tropas e da população. Por isso a doença pareceu ter surgido na Espanha, e o nome se deve ao controle dos relatos oriundos dos campos de batalha (C). O texto não trata de medicina militar (A), retaliação a desertores (B), armas biológicas (D) ou refugiados (E).'),
    -- 1º Dia, 55. Gabarito: E.
    ('1º Dia', '3ccfb1afd5283503e364dcb30d0f478380a87da2f84e3ce06d2893027c6a49c3', 'O Texto I mostra que, a partir do século IV, os imperadores cristãos condenaram o teatro e a dança, a ponto de recusar o batismo a artistas e excomungar quem fosse ao teatro em dias santos, o que expressa dogmatismo religioso. O Texto II mostra a dança incorporada ao culto gospel, com aceitação, expansão e um mercado próprio, o que expressa a adesão dos fiéis (E). Os textos não tratam de segregação social (A), sacramentos (B), transe ou progresso intelectual (C) nem de penitência e juramento (D).'),
    -- 1º Dia, 56. Gabarito: E.
    ('1º Dia', '256d2bd1b84ca8d3b293812727f242955c4efa3f6e6cbcee8c9fc4fc364d9841', 'O autor argumenta que o chamado “êxodo urbano” se restringe a uma pequena fração da elite: quem compra uma segunda residência ou quem, com emprego estável e renda alta, muda-se para cidades do interior para reproduzir ali a vida metropolitana. A crítica evidencia a seletividade dos deslocamentos populacionais (E). Esses migrantes não valorizam tradições rurais (A), e o texto não trata de plantações (B), comércio (C) ou rodovias (D).'),
    -- 1º Dia, 57. Gabarito: D.
    ('1º Dia', '789abc10773d8d41b1f75939aa1453bfd59b7faaca842cef125cbd0295dd54e1', 'Foucault descreve a disciplina não como descoberta súbita, mas como “uma multiplicidade de processos muitas vezes mínimos”, “de localizações esparsas”, que funcionam em colégios, escolas, hospitais e quartéis. Isso indica a capilarização das práticas de controle, que se espalham pelas instituições do cotidiano (D). O suplício (A) e a espetacularização das penas (E) são próprios do modelo punitivo que a disciplina substitui, e o texto não fala de judicialização (B) nem de distinções de nobreza (C).'),
    -- 1º Dia, 58. Gabarito: C.
    ('1º Dia', 'e6662e8fa8f04a1c09ce3024e3d81345f1b6765ae226f6228cc08d797681601c', 'A queda do nível do Rio Reno impede a navegação fluvial em parte do ano. Como o transporte hidroviário é o modo mais barato para grandes volumes de carga, as indústrias precisam reduzir a carga dos barcos ou recorrer a rodovias e ferrovias, o que encarece a logística de transporte (C). O texto não trata de mineração (A), pesca (B) ou agricultura de subsistência (D), e o efeito é o aumento de custo, não o sucateamento da indústria (E).'),
    -- 1º Dia, 60. Gabarito: A.
    ('1º Dia', '2613ff06bb2ad33282745e936eac913ccaf40c84ec9ecc4ab42b3a1a24accd45', 'Para Derrida, o direito é calculável e aplicado por regras, enquanto a justiça é “incalculável” e nunca garantida por uma regra; logo, pode haver ação justa contrária ao ordenamento jurídico. O exemplo típico é a desobediência civil, em que se descumpre deliberadamente uma lei considerada injusta em nome da justiça (A). A repressão estatal é aplicação da força do direito (B), e conflitos intercontinentais (C) e manifestações sindicais (D) ou estudantis (E) não implicam, em si, desconformidade com a lei.'),
    -- 1º Dia, 61. Gabarito: D.
    ('1º Dia', 'c35b0e4d465e3f1a3f4f0011cac8e0427d3adc13cfa997e1e06c768693d9f67b', 'Os dois amigos se encontram no sinal fechado e trocam frases apressadas e prontas (“Quanto tempo...”, “Pra semana, prometo”, “Quando é que você telefona?”) até o sinal abrir, justificando a pressa como “a alma dos nossos negócios”. A canção, de 1970, retrata uma situação que permanece atual: a efemeridade dos vínculos afetivos na vida urbana acelerada (D). A pressa por “pegar meu lugar no futuro” indica competição, e não sua diminuição (A); a memória falha, em vez de ser valorizada (B); e o texto não fala de mobilidade urbana (C) nem de meios de comunicação obsoletos (E).'),
    -- 1º Dia, 62. Gabarito: B.
    ('1º Dia', '68d7f76b13ebbc8f9f00bb1c5290a39622206a91ed3ce675e1c0fde178841ddc', 'A Flórida tem subsolo de calcário, rocha que se dissolve lentamente pela ação da água da chuva, levemente ácida. A dissolução forma cavidades subterrâneas, e quando o teto delas cede surgem as dolinas que engolem construções. O desmoronamento tem origem na ação do intemperismo químico (B). Não há cristalização da rocha (A), mata ciliar (C) ou acúmulo de sedimentos orgânicos (D), e a impermeabilização do solo (E) não é a causa apontada.'),
    -- 1º Dia, 63. Gabarito: A.
    ('1º Dia', '0a897788e4741f454d00257edd3e920e4ad39a65f6cb5c5127d393126585ba29', 'O East Side Gallery é um trecho original do Muro de Berlim, tratado como patrimônio cultural e histórico da cidade por lembrar a divisão da Alemanha durante a Guerra Fria. Demoli-lo para erguer um condomínio de luxo representa uma violação da memória coletiva (A). A demolição não muda fronteiras políticas, já que o muro caiu em 1989 (B), e o texto não trata de arquitetura neoclássica (C), influências orientais (D) ou mobilidade urbana (E).'),
    -- 1º Dia, 64. Gabarito: D.
    ('1º Dia', '7b23d73379174a3a4f6c7034b45b46a12df6367e76d21390c3c2811aebaa601a', 'Os fragmentos expressam a doutrina heraclitiana da unidade dos contrários: “unido e separado, em consonância e em dissonância”, “dia-noite, inverno-verão, guerra-paz, saciedade-fome”. O cosmos é pensado a partir de pares opostos que se completam, o que corresponde à distribuição dicotômica do cosmos (D). A imobilidade do universo é tese de Parmênides, e não de Heráclito, que enfatiza o devir (C); os contrários formam uma harmonia, e não uma desordem (E); e os fragmentos não falam de algo imperecível (A) ou de degradação da natureza (B).'),
    -- 1º Dia, 65. Gabarito: A.
    ('1º Dia', 'e7c40f8218275e5201df8eb872b1a34742511b659b2e7397ec28ca144a1f0a47', 'Para os europeus, comer carne humana era “abominável” e sinônimo de “barbarismo e da incapacidade de se autogovernar”, ou seja, selvageria. Para os tupis, era um ritual regrado, em que o guerreiro se sentia honrado ao morrer em um banquete canibal, o que confere à prática um sentido de honra e fortalecimento, isto é, de empoderamento (A). As demais alternativas não correspondem aos significados atribuídos pelo texto a cada grupo.'),
    -- 1º Dia, 66. Gabarito: B.
    ('1º Dia', 'f4bd26b6be44e3415592c91458d91080c190e48dc92368c57cc8de2656f7de29', 'Prandi aponta dois fatores na invisibilização das religiões afro-brasileiras: estarem fragmentadas em pequenos grupos, sem “algum tipo de organização ampla”, o que é uma precariedade de coesão representativa, e carregarem “o peso do preconceito racial”, o que é uma recusa da alteridade (B). O texto não fala de partidos ou laicidade (A), de estruturas decisórias ou diálogo (C), de ausência de direitos constitucionais (D) nem de debilidade do pertencimento étnico (E).'),
    -- 1º Dia, 67. Gabarito: B.
    ('1º Dia', 'ff4e976f853a04660aec6764cc6182719791dbeefe269881fbda821147b5a3ce', 'Os inseticidas sintéticos não matam só as pragas: atingem também insetos benéficos, como abelhas e outros polinizadores. Seu uso crescente nos espaços agrícolas provocou a diminuição da diversidade de polinizadores naturais (B). A contaminação dos lençóis freáticos aumenta, e não diminui (C); os defensivos buscam elevar a produtividade (D); e a desagregação do solo (A) e a erosão laminar (E) não dependem do uso de inseticidas.'),
    -- 1º Dia, 68. Gabarito: C.
    ('1º Dia', '227d3501634fec70ec2d6ae91054f9e1e09f6ff4aef3158e45eb45dc0d6da6bd', 'Bobbio afirma que o elenco dos direitos do homem mudou e continua mudando conforme as condições históricas: as necessidades, os interesses, as classes no poder e as transformações técnicas. Direitos tidos como absolutos foram limitados, e outros, como os sociais, foram incorporados. Os direitos humanos são, portanto, construções históricas, ou seja, convenções coletivas (C). O texto nega que sejam atemporais (B), mostra que dependem de condições concretas e não são espontâneos (A), e não os associa a resquícios religiosos (D) nem a meras imposições políticas (E).'),
    -- 1º Dia, 70. Gabarito: B.
    ('1º Dia', '65c639e99d52bfc8265f5c461b92bb884b8b04871c6fb459cc2ccc66ee4b4ead', 'A Roda dos Expostos acolhia recém-nascidos abandonados com base em “práticas caritativas, paternalistas e imediatistas” voltadas ao cuidado básico e, sobretudo, “à salvação da sua alma, via batismo”. Justificava-se por um preceito de natureza sociorreligiosa: a caridade cristã somada ao amparo social (B). A noção de direitos humanos é posterior (A); o abandono anônimo rompia os vínculos familiares, em vez de reconhecê-los (C); e o texto não menciona discurso científico (D) ou abolicionismo (E).'),
    -- 1º Dia, 71. Gabarito: A.
    ('1º Dia', 'e419271b47d6f452c2e3ca36f58818770a4f6bcdcea2e1388dcf4064f8972340', 'Para Bentham, o governo deve promover a felicidade, entendida como prazer e ausência de dor, e a necessidade de punir é proporcional ao quanto uma ação perturba essa felicidade. A punição não vale por si mesma: é um meio justificado pelo fim que promove, o que caracteriza a justiça utilitarista e consequencialista como aplicação de meios para atingir um fim (A). A imposição de regras para estabelecer um dever (B) é própria da ética deontológica, e o texto não fundamenta a punição em princípios de direito (C), prescrições (D) ou costumes (E).'),
    -- 1º Dia, 72. Gabarito: C.
    ('1º Dia', '271674a34891d35164bf02059124c55c02015843fc6ba008a6798699fb9947e4', 'A cidade sustentável descrita no texto recusa a relação “natureza-objeto” e busca uma ação sinérgica entre prudência ecológica, eficiência energética e equidade. Canalizar rios e córregos trata o curso d’água como objeto a ser controlado: impermeabiliza as margens, elimina as várzeas e agrava as enchentes, contradizendo esse modelo (C). A coleta seletiva (A), o reaproveitamento da água da chuva (B), a arborização (D) e a educação ambiental (E) são medidas compatíveis com a sustentabilidade.'),
    -- 1º Dia, 73. Gabarito: B.
    ('1º Dia', '18ff43baf2ee66e38490b0d43e3cd2e37f6ccee9cd2c5e7263404240c4cd46e8', 'Para Bauman, a utopia nasce quando se percebe que o mundo “não está funcionando adequadamente” e há confiança de que os seres humanos podem identificar o que está errado e transformá-lo. Sua função nas transformações sociais é, portanto, apontar alternativas possíveis à realidade (B). A utopia se volta para o futuro, e não para memórias (A) ou experiências passadas (C); não busca perpetuar paradigmas (D), mas revê-los; e é um horizonte que orienta a mudança, não a execução de soluções conclusivas (E).'),
    -- 1º Dia, 75. Gabarito: A.
    ('1º Dia', '283eb92ea36382412d9dd1c451ab82fdef9347ccd9b0fc004235f4f795ab8411', 'Em agosto de 1954, membros da guarda pessoal de Vargas organizaram o atentado da Rua Tonelero contra Carlos Lacerda. Lacerda foi ferido e o major da Aeronáutica Rubens Vaz morreu. A ligação do crime com o Palácio do Catete deu munição à UDN e a setores militares, que intensificaram os ataques e passaram a exigir a renúncia do presidente, o que culminou no suicídio de Vargas dias depois (A). A comoção popular em defesa de Vargas (C) veio depois de sua morte, e o atentado não provocou intervenção sindical (B), fim da censura (D) ou apoio do Congresso à oposição (E).'),
    -- 1º Dia, 76. Gabarito: C.
    ('1º Dia', 'e45c9d7c84be4d5aaeddff75547ffb8717f9c79921be33d5d57ae690f7ae716e', 'Clarice diz que gostaria de ter sido “uma pessoa que luta pelo bem dos outros”, que desde criança defendia quem fosse acusado e que vivia perplexa diante das injustiças sofridas pelos menos privilegiados. A reflexão remete ao pensamento altruísta, que valoriza a ação em favor do outro (C). A eudaimonia (A) e o hedonismo (B) se centram na felicidade ou no prazer do próprio sujeito; o apelido “protetora dos animais” era uma brincadeira, e ela defendia pessoas, o que afasta o antiespecismo (D); e não há cálculo de utilidade prática (E).'),
    -- 1º Dia, 77. Gabarito: D.
    ('1º Dia', 'd9d4e515c535cdf5938b4299fd09796525908a8441149affa2c9c8ae3a583196', 'Marcuse descreve uma sociedade que, ao atender às necessidades dos indivíduos e elevar o padrão de vida, esvazia a função crítica da autonomia e da oposição política e torna o não conformismo “socialmente inútil”. É a sociedade unidimensional, em que a dimensão crítica e negadora é absorvida pelo sistema (D). A desobediência civil é justamente o que perde espaço (C), e o desenvolvimento tecnológico (E) é o contexto, não a característica apontada. O texto não fala em relativismo moral (B) nem em gestão integrada (A).'),
    -- 1º Dia, 78. Gabarito: D.
    ('1º Dia', '88c209dce2ca21c152ef82d0007844f52f475a677cc2b9b9d2c8fa43394d362e', 'A fazenda Cabaceiras foi desapropriada por descumprir a função social da terra prevista na Constituição de 1988, por causa do trabalho análogo à escravidão e das infrações ambientais. Ao destinar terras concentradas e mal utilizadas a outros fins, como a reforma agrária, a justiça atua como mecanismo de revisão das desigualdades econômicas (D). A decisão contraria a manutenção da ordem agrária (A), limita a propriedade privada em vez de legitimá-la (B) e se opõe aos interesses das classes dominantes (C); uma desapropriação, porém, não homogeneíza a distribuição fundiária (E).'),
    -- 1º Dia, 80. Gabarito: C.
    ('1º Dia', '263b75bfaf679918d4e6654484f5702cc08f6b45ca0b41ae55b6e2a183e03fb6', 'O texto descreve o contexto das Cruzadas: a Igreja abriu “as portas da graça” a todos os fiéis, com a única condição de partirem para o Oriente e lutarem contra os inimigos de Cristo. Assim, os leigos podiam obter a salvação sem renunciar ao seu estado, por meio de uma ação voluntária, o engajamento na expedição (C). A salvação não dependia de textos (A), de liturgia, que era atribuição do clero (B), de ideias messiânicas (D) ou de celebrações coletivas (E).'),
    -- 1º Dia, 81. Gabarito: C.
    ('1º Dia', '5545e5ec786e805650341503d1945231f8275442c3c628f034cf1ba9496f6529', 'Climatizar edifícios com ar-condicionado consome muita eletricidade. A troca de calor com o subsolo reduz essa demanda, e como a matriz elétrica brasileira depende sobretudo das hidrelétricas, a expansão da tecnologia tende a reduzir a pressão sobre essas usinas (C). A geotermia diversifica a matriz, em vez de homogeneizá-la (A); reduz o consumo elétrico, em vez de ampliá-lo (B); não se relaciona com o consumo industrial (D); e é ela mesma um recurso renovável (E).'),
    -- 1º Dia, 82. Gabarito: B.
    ('1º Dia', 'c98f7654b594f64a221ce36a20003f876f616feba84dc1f1b9e0bd22382ef85a', 'Sem leis escritas, os patrícios manipulavam a justiça a seu favor. Os plebeus contestaram essa situação e, ao longo de séculos de lutas, conquistaram o tribunato da plebe, a Lei das Doze Tábuas (leis escritas e públicas) e o acesso às magistraturas. Eles almejavam participar da vida política (B). A monarquia já havia acabado na República (A), os nobres eram os próprios patrícios beneficiados (C), e o texto não trata de jornada de trabalho (D) ou de estrangeiros (E).'),
    -- 1º Dia, 83. Gabarito: C.
    ('1º Dia', '9577eee177a5939b26b4be1b36915785f55bd3a769bddb96044100bf709f00e2', 'A Declaração reconhece aos povos indígenas o direito sobre um amplo conjunto de conhecimentos: ciências, tecnologias, recursos genéticos, sementes, medicamentos, propriedades da fauna e da flora, transmissões orais, literaturas, artes e esportes. Esses direitos representam a complexidade dos saberes tradicionais (C). As línguas não são o foco (A), o texto protege os saberes contra influências externas em vez de ampliá-las (B), e reduzi-los a práticas de sobrevivência (D) ou à economia de subsistência (E) ignora sua amplitude.'),
    -- 1º Dia, 84. Gabarito: E.
    ('1º Dia', 'efcf435a3e8635d3409d41127a9f9d577de70e7544df5988b1335e887a56f50a', 'No Texto I, Deus concede a Bezalel competência para o trabalho artístico, a ourivesaria, a lapidação e o entalhe; no Texto II, a sabedoria dos egípcios torna Moisés “poderoso em palavras e obras”; no Texto III, o conhecimento da “ciência certa” leva a renunciar à ostentação. Os três textos mostram o saber orientando o trabalho e a vida em sociedade, isto é, o desenvolvimento social e as práticas laborais (E). Os textos não tratam de universidades (A), seitas (B), intolerância (C) ou rituais místicos (D).'),
    -- 1º Dia, 85. Gabarito: A.
    ('1º Dia', 'd5d3046ef44e556d116c6b3548104865a9ab720316d3dc0b2f3d74b5ee8b7dd7', 'No início do século XX, as potências europeias, entre elas a Rússia czarista, enviavam expedições científicas para coletar espécimes e objetos etnográficos de povos de outros continentes e exibi-los em seus museus. Essas coleções reforçavam o prestígio nacional e uma visão de domínio sobre territórios e culturas tidos como exóticos, o que liga a expedição a um projeto nacionalista de caráter imperialista e colonizador (A). A expedição era civil e científica, não militar (B), e seus objetivos não eram lúdicos ou filantrópicos (C), comerciais (D) ou religiosos (E).'),
    -- 1º Dia, 86. Gabarito: E.
    ('1º Dia', 'b11cd3562c1bcf329000ba5a44e9f643fa8f1e14e279d8bfd2eaf61a89696fd2', 'A discriminação positiva consiste em políticas que tratam de forma diferenciada um grupo em desvantagem para promover igualdade real, e não só formal. A criação de delegacias especializadas no atendimento à mulher é um exemplo atual desse tipo de política (E). O sufrágio universal (A) e a redução da jornada (B) são medidas gerais, não voltadas às mulheres, e extinguir o crime de feminicídio (C) ou reduzir a licença-maternidade (D) diminuiria a proteção às mulheres.'),
    -- 1º Dia, 87. Gabarito: E.
    ('1º Dia', '92a53644a7b3bd24c304db8c44264b1974f314300a009ace5c1bcedbb6cc30a9', 'Na cidade ideal de Platão, a justiça consiste em cada classe cumprir sua função para o bem da pólis, sob o governo dos filósofos, que conhecem o Bem; a cidade injusta é governada por proprietários que buscam interesses particulares. A legitimidade do governo depende de sua orientação ao bem comum, o que mostra a indissociabilidade entre ética e exercício do poder (E). O texto não trata de relação intersubjetiva (A), mitologia (B) ou retórica (C), e as virtudes cardeais (D) não são o ponto destacado.'),
    -- 1º Dia, 88. Gabarito: D.
    ('1º Dia', '253016a677a3151c55a62c64d10fe05017553e288a02b07c3b91902f9b214f7e', 'A Impressão Régia foi criada com a chegada da Corte, em 1808, e, segundo o texto, atuou “na legitimação e sustentação” do projeto de um novo império português na América. Ao publicar atos oficiais e periódicos que difundiam a autoridade da Corte pelo território, inclusive nos sertões, ela ajudou a integrar as regiões ao poder central sediado no Rio de Janeiro (D). Não havia imprensa livre a ser regulada (A); a função ia além de transmitir ordens às capitanias (B), pois buscava legitimar o projeto; e o público visado estava na América, não nas metrópoles europeias (C) ou nas elites lusitanas (E).'),
    -- 1º Dia, 89. Gabarito: D.
    ('1º Dia', '2aeb0aeb1c01561e2e421480879a930d190ee980399d8e67ee51dea5e4186953', 'O modelo de previsão do comportamento do fogo foi desenvolvido pelo Centro de Sensoriamento Remoto da UFMG com dados de satélite do Inpe, combinando relevo, ventos, umidade e biomassa seca para apontar áreas de risco. Isso indica a importância das pesquisas acadêmicas na proteção ambiental (D). O texto não trata de produção orgânica (A), estradas (B), cosmologias indígenas (C) ou interesses estrangeiros (E).'),
    -- 1º Dia, 90. Gabarito: B.
    ('1º Dia', '98c7aa52584861a40e0cd1a4d76ce6789731ddf0c70440d516af10278e7d4299', 'O Texto I apresenta o cinema como “encanto indefinível”, que oferece entretenimento e ocasião de encontros sociais. O Texto II critica a falta de cuidado na escolha dos filmes exibidos às crianças, causa de “inúmeros dissabores” para os pais. Os textos apresentam argumentos contrários sobre o mesmo tipo de diversão (B), e não conclusões semelhantes (A) ou justificativas idênticas (E). Nenhum deles trata de didática escolar (C) ou de regras teológicas (D).'),
    -- 2º Dia, 91. Gabarito: C.
    ('2º Dia', 'dfd989176363a825ca114d55ccc9349dc36e3aeab098478172f642b04fa42489', 'O monstro de gila vive em um deserto, ambiente quente e seco, com escassez de água e de alimento. Se espécies aparentadas tendem a apresentar adaptações semelhantes em ambientes semelhantes, o bioma brasileiro mais provável é a Caatinga, de clima semiárido, chuvas escassas e irregulares e longos períodos de seca (C). O Cerrado tem estação chuvosa bem definida (A), os Pampas têm clima subtropical úmido (B), a Restinga é litorânea (D) e o Pantanal é uma planície alagável (E).'),
    -- 2º Dia, 92. Gabarito: D.
    ('2º Dia', 'fc1927cf4cf4259526e9b88c695e9eb1ad4d457331a29fbcd55d54bc5ec34d3e', 'A destilação separa a água dos sais dissolvidos: a água evapora e é condensada, e os sais ficam no recipiente. A água destilada é usada em laboratórios, como solvente industrial e em baterias, mas não é adequada para o consumo contínuo por não conter os sais minerais de que o organismo precisa (D). Água dura é justamente a rica em íons Ca²⁺ e Mg²⁺ (A), água pesada é D₂O (B), água sanitária é uma solução de hipoclorito de sódio (C) e água oxigenada é H₂O₂ (E).'),
    -- 2º Dia, 93. Gabarito: A.
    ('2º Dia', '67a1e4e66c415464fd25aca075c3d2d5e177d8be79939a6bf6db1e042bb6c73b', 'Em ambientes escuros, a pupila se dilata para captar mais luz. O flash é rápido demais para que ela se contraia a tempo, então muita luz atinge o fundo do olho, rico em vasos sanguíneos, e é refletida de volta à câmera com a cor vermelha. Por isso o efeito é mais comum à noite: com a pupila dilatada, chega mais luz à retina (A). A pupila retraída é típica de ambientes claros (B, C, D), e com ela dilatada chega mais luz, e não menos (E).'),
    -- 2º Dia, 94. Gabarito: E.
    ('2º Dia', '135bd0976280f2ba848f024ac773a85a689248d8579bdbde55bc4175014bfd68', 'A tetrodotoxina é produzida e armazenada nas gônadas e vísceras do baiacu. Se esses órgãos forem rompidos durante o preparo, a toxina contamina o filé, então a intoxicação pode ser evitada manuseando o peixe sem romper os órgãos internos (E). Como a toxina é termoestável, cozinhar ou fritar não a destrói (C); a higiene evita contaminação por microrganismos, mas não remove uma toxina do próprio peixe (D); e, segundo o texto, o peixe produz a toxina, de modo que o modo de criação (A) ou de pesca (B) não a elimina.'),
    -- 2º Dia, 95. Gabarito: A.
    ('2º Dia', 'bfbbc6731373645156363915fc0cb87b6fefaf107a8c40bde5491bbee6416a60', 'A lipase ácida é uma enzima digestiva que atua em pH ácido, condição encontrada no interior dos lisossomos, organelas responsáveis pela digestão intracelular. Sem ela, os lisossomos não degradam ésteres de colesterol e triglicerídeos, que se acumulam nas células, o que caracteriza uma doença de depósito lisossômico (A). Ribossomos sintetizam proteínas (B), mitocôndrias fazem a respiração celular (C), peroxissomos realizam oxidações em pH neutro (D) e o retículo endoplasmático liso sintetiza lipídios, em vez de degradá-los (E).'),
    -- 2º Dia, 96. Gabarito: A.
    ('2º Dia', '705c931ec060afcf141f3420a24ea9b30046938341c9060391aaaa2ae3881e23', 'Na fotossíntese, as plantas absorvem CO₂ da atmosfera e fixam o carbono em sua biomassa. Plantar mais árvores é, portanto, a ação que remove o gás já presente na atmosfera (A). Usinas eólicas (B), energia solar (C), manter os combustíveis fósseis no solo (D) e reduzir resíduos (E) diminuem novas emissões, mas não retiram o CO₂ que já está no ar.'),
    -- 2º Dia, 97. Gabarito: C.
    ('2º Dia', 'd69f9fbb36053694bd12e635fb58ca82fd61bff45d3ee4c62b57ae6588aa4353', 'O calor da lâmpada chega às mariposas de dois modos: por convecção, que depende do movimento de um fluido (o ar aquecido), e por irradiação, a emissão de ondas eletromagnéticas (sobretudo infravermelho), que se propagam até no vácuo. O processo que independe da presença de fluidos é a irradiação (C). A convecção exige fluido (E), e reflexão (A), refração (B) e dispersão (D) são fenômenos ópticos, não processos de transferência de calor.'),
    -- 2º Dia, 98. Gabarito: B.
    ('2º Dia', 'efd69b067b624fab7e994670d3c30e3fb4e807e2667644586d71b5d3e5379620', 'Os sapos não produzem o veneno: obtêm-no ao comer formigas e cupins que se alimentam de plantas tóxicas. Em cativeiro, sem essa dieta, não acumulam a toxina. A perda da toxicidade se deve à ausência da alimentação natural (B). A umidade (A), a adaptação ao ambiente (C) e o comportamento (D) não explicam a perda, e a genética dos animais é a mesma dentro e fora do cativeiro (E).'),
    -- 2º Dia, 100. Gabarito: D.
    ('2º Dia', 'f7e25fb4fa304ab91e161790a8ca30412f09374f71e64b652e5378992ac65a22', 'O capim-gordura é uma espécie exótica invasora: agressivo e muito competitivo, espalha-se por grandes áreas e disputa com as plantas nativas espaço, luz, água e nutrientes. Em longo prazo, tende a diminuir as espécies nativas do Cerrado (D). A invasão reduz a diversidade de nichos, em vez de ampliá-la (A); o capim acumula biomassa seca e aumenta o risco de queimadas (E); e assoreamento (B) e infiltração de água (C) não são a consequência destacada.'),
    -- 2º Dia, 104. Gabarito: E.
    ('2º Dia', 'ec29089cab668461dabdcf787837fd7d5a327d862b85725da10ed809e1dac7fe', 'O número de meias-vidas no período é 26,5 ÷ 5,3 = 5. A cada meia-vida a massa cai pela metade: 2,00 mg → 1,00 → 0,50 → 0,25 → 0,125 → 0,0625 mg. Ou seja, m = 2,00 ÷ 2⁵ = 2,00 ÷ 32 ≈ 0,06 mg (E). O valor 0,13 mg (D) corresponde a só quatro meias-vidas.'),
    -- 2º Dia, 106. Gabarito: D.
    ('2º Dia', '25990f3161180dede6ce30f061c0dbfcd33877989230ffb0cb35bc6b1fffa1f5', 'O betacaroteno é convertido em vitamina A no organismo. A vitamina A forma o retinal, que compõe a rodopsina, pigmento dos bastonetes responsável pela visão em baixa luminosidade; sua carência causa a cegueira noturna (D). A hemofilia é uma doença genética da coagulação (A), o escorbuto vem da falta de vitamina C (B), o raquitismo, da falta de vitamina D (C), e a anemia perniciosa, da deficiência de vitamina B12 (E).'),
    -- 2º Dia, 113. Gabarito: B.
    ('2º Dia', 'e0e4adc745678847cb3e9b95c9e39f8c0d9140b9b82f9e9b0af3f05bf7aa4749', 'A dimetilamina, (CH₃)₂NH, é uma amina e, portanto, uma base orgânica. O vinagre contém ácido acético, que a neutraliza e forma um sal de amônio (acetato de dimetilamônio), composto iônico e não volátil. Assim, o produto deixa de evaporar quando a temperatura sobe (B). A água apenas a dissolve e espalha (A), o óleo não reage com ela (C), o sal de cozinha é neutro (D) e o bicarbonato de sódio tem caráter básico, sem neutralizar uma base (E).'),
    -- 2º Dia, 117. Gabarito: E.
    ('2º Dia', 'cecec8324577739c5c1408bf857fabf436a3bf48e035aa2f604333ff6e5535b5', 'A quantidade de nióbio é 9 300 g ÷ 93 g/mol = 100 mol. Pela equação, 10 mol de Al produzem 6 mol de Nb, então a quantidade estequiométrica de Al é 100 × 10/6 ≈ 166,7 mol, ou seja, 166,7 × 27 = 4 500 g = 4,5 kg. Com o excesso de 10%: 4,5 × 1,10 = 4,95 kg, cerca de 5,0 kg (E). O valor de 4,5 kg (D) ignora o excesso de alumínio.'),
    -- 2º Dia, 119. Gabarito: B.
    ('2º Dia', 'aab02078034a75c91de25a7631ab74b0cd1f0cd35d57208ed5cc79b48bf460d9', 'No escurecimento, a prata é oxidada a Ag₂S, e o oxidante é o O₂: ΔE° = E°(O₂) − E°(Ag₂S/Ag) = +1,23 − (−0,69) = +1,92 V. No clareamento, o alumínio, mais reativo, se oxida e reduz o Ag₂S de volta a prata metálica, com a solução de NaCl atuando como eletrólito: ΔE° = E°(Ag₂S/Ag) − E°(Al³⁺/Al) = −0,69 − (−1,68) = +0,99 V. Os valores são +1,92 V e +0,99 V (B), ambos positivos, como se espera de reações espontâneas.'),
    -- 2º Dia, 120. Gabarito: B.
    ('2º Dia', '89d69a3053f5c34d8f65a7e732e6ac2c232a8b2b02b2c2e23b738d1cae6cfb3e', 'Pela equação dos gases ideais, a quantidade de gás necessária é n = PV/RT = (1,00 × 4,00) ÷ (0,082 × 453) ≈ 0,1077 mol. Cada mol de NH₄HCO₃ gera 3 mol de gases (NH₃, CO₂ e H₂O), então seriam necessários 0,1077 ÷ 3 ≈ 0,0359 mol do sal com rendimento de 100%. Com rendimento de 80%: 0,0359 ÷ 0,80 ≈ 0,0449 mol. A massa é 0,0449 × 79 ≈ 3,5 g (B).'),
    -- 2º Dia, 122. Gabarito: C.
    ('2º Dia', 'f646779c30316fc58b4c323ccb4a4f4f3d03d4d99b633ca441cd817c8063b5be', 'As cangas são ambientes extremos (solos ácidos, rasos, pobres em nutrientes e superfícies que chegam a quase 70 °C) e isolados, como “ilhas” de ferro. A seleção favorece espécies especializadas nessas condições, que só ocorrem ali, ou seja, endêmicas, o que coincide com a “distribuição restrita” citada no texto (C). Espécies exóticas são introduzidas de outros lugares (A), migratórias se deslocam entre ambientes (B), e generalistas (E) ou dominantes (D) não são favorecidas por condições tão específicas.'),
    -- 2º Dia, 123. Gabarito: D.
    ('2º Dia', '3390cd9cdee7adbdd776ddeba2ef5b8554917ead8a5a4d5b75c21327dce9970a', 'Pelo princípio de Le Chatelier, aumentar a concentração (pressão parcial) de um reagente desloca o equilíbrio no sentido dos produtos. Aumentar a pressão parcial de Cl₂ favorece, portanto, a formação de TiCl₄ (D). Há 2 mol de gás de cada lado (2 Cl₂ ⇌ TiCl₄ + O₂), então a pressão total não desloca o equilíbrio (A); a reação é endotérmica, e baixar a temperatura favorece os reagentes (B); aumentar o O₂, que é produto, desloca o equilíbrio para a esquerda (C); e o TiO₂, por ser sólido, não interfere no equilíbrio (E).'),
    -- 2º Dia, 124. Gabarito: C.
    ('2º Dia', 'b49775c680f8a9052dcc16475cd56228ee6cd49260a6dc58bf101e387dc3913e', 'A pressão de uma coluna de produto sobre a laje é P = d · g · h, que não depende da área. Para não ultrapassar 10⁴ Pa: h = P ÷ (d · g) = 10⁴ ÷ (1 250 × 10) = 10⁴ ÷ 12 500 = 0,80 m (C). A área útil de 50 m² limita a quantidade total armazenada, mas não a altura máxima de empilhamento.'),
    -- 2º Dia, 130. Gabarito: D.
    ('2º Dia', '221649c6e5981f2a68fe549e9e18a54ab74ef8702d86cf92589d9d9fe2d3e800', 'A bactéria geneticamente modificada é uma E. coli que recebeu os genes do relógio circadiano da cianobactéria S. elongatus. Ela continua com seu genoma original, inclusive os genes do próprio metabolismo, e passa a ter os genes circadianos de S. elongatus (D). Como a E. coli é um organismo não circadiano, não possui genes de ciclo circadiano próprios (B, C, E), e a alternativa A ignora os genes transferidos.'),
    -- 2º Dia, 131. Gabarito: C.
    ('2º Dia', '8b59e247ad72a781e172b99a0706b7733f985f8b17bd853e15fcb86ffafb7f77', 'As aves aquáticas espalham nas penas, com o bico, o óleo produzido pela glândula uropigial, localizada na base da cauda. Esse óleo impermeabiliza a plumagem e mantém o ar retido entre as penas, o que garante a flutuação. Com menos secreção, as penas se encharcam e as aves se afogam (C). O papo armazena alimento (A), a troca de penas (B) não impede o encharcamento, a membrana natatória auxilia a propulsão no nado (D) e os ossos pneumáticos não se relacionam com o encharcamento das penas (E).'),
    -- 2º Dia, 137. Gabarito: D.
    ('2º Dia', '623bd9497f4e36482e977016a1af9b770d5a535430b8d5db83583d91ae69610c', 'As faces visíveis do poliedro são: a base livre do prisma (hexágono regular), as 6 faces laterais do prisma (retângulos congruentes entre si), as 6 faces laterais do tronco (trapézios isósceles congruentes entre si) e a base menor do tronco (hexágono regular menor). A base maior do tronco coincide com uma base do prisma e fica no interior da peça. São quatro classes de faces congruentes: hexágono maior, retângulos, trapézios e hexágono menor, portanto 4 cores (D).'),
    -- 2º Dia, 139. Gabarito: B.
    ('2º Dia', '9e78a32fafe8c2c9ad0af567fa43464e800fbdf0f4076e2835dcbe97d807e630', 'A diferença entre a marca de referência e o recorde de Bolt é 10,00 − 9,58 = 0,42 segundo (B).'),
    -- 2º Dia, 141. Gabarito: C.
    ('2º Dia', '6de3f827794a8f3ca0504d1cd9ec4e96bb662832829a05e9d955cc946915ebe5', 'Por semana, o carro roda 30 km × 7 = 210 km. Com consumo de 1 m³ a cada 13 km, precisa de 210 ÷ 13 ≈ 16,2 m³ de GNV. Como o preço é proporcional à capacidade, a pessoa escolhe o menor cilindro que comporte esse volume: o de 17 m³ (C). O de 14 m³ não garante um único abastecimento semanal (B).'),
    -- 2º Dia, 144. Gabarito: E.
    ('2º Dia', '3355cf0484e4f47e8ebe877baac1ac92b7dec14d73b51935df5068080446dd05', 'A quantidade de S₂ é 0,05% de 10 L, isto é, 0,005 L, e ela não muda. Na nova solução, S₂ deve representar 100% − 99,90% = 0,10% do total, então o volume total será 0,005 ÷ 0,001 = 5 L. É preciso retirar 10 − 5 = 5,0000 L de S₁ (E). O resultado parece grande porque dobrar a fração de S₂ (de 0,05% para 0,10%) exige reduzir o volume total à metade.'),
    -- 2º Dia, 145. Gabarito: C.
    ('2º Dia', 'ce5e0e27d9eb56ea6716ea752ac87191f4c5eb5b46863d9da0a1c6d96ac90ee7', 'No pedido anterior, a distribuidora enviou 10 200 L e o posto recebeu 9 900 L, então o descarte fixo do transporte é 10 200 − 9 900 = 300 L. O novo pedido é o dobro do volume encomendado antes: 2 × 10 000 = 20 000 L. Como o descarte independe da quantidade transportada, a distribuidora deve enviar 20 000 + 300 = 20 300 L (C).'),
    -- 2º Dia, 148. Gabarito: D.
    ('2º Dia', '64d4fdb0390f5e331c4aba1dd1a2d8ec94aa74d80c22ae1afe14607309592f7b', 'Cada funcionário produz 720 ÷ (3 × 6) = 40 tijolos por hora. Com 5 funcionários trabalhando 9 horas por dia, a produção diária passa a ser 5 × 9 × 40 = 1 800 tijolos (D).'),
    -- 2º Dia, 149. Gabarito: D.
    ('2º Dia', 'b79cb6a2d3cb6901105b7b98065fa50053b39cf5c1d986a48545151e2698f00f', 'Montando o código da esquerda para a direita: andar 2; setor 08; funcionário 109; chegada pela manhã, dígito 0. O código é 2 08 109 0 = 2081090 (D).'),
    -- 2º Dia, 150. Gabarito: D.
    ('2º Dia', '9b7ca82a08d8fabe2f0586b599e72e399c59472467dcc8cab480c729f589dddc', 'Os 4 envelopes podem ser devolvidos de 4! = 24 maneiras igualmente prováveis, e só uma delas devolve a cada candidato o próprio celular. A probabilidade é 1/24 (D).'),
    -- 2º Dia, 157. Gabarito: B.
    ('2º Dia', '9351497ab72aa4b74e5aca31ec16688f58628c759a58bf71277f2222138cf88c', 'Se reciclar custa R$ 500,00 por tonelada e isso equivale a 5% do custo com derivados de petróleo, este é 500 ÷ 0,05 = R$ 10 000,00 por tonelada. O custo do mês foi 110 × 10 000 + 80 × 500 = R$ 1 140 000,00, então a meta é gastar no máximo R$ 570 000,00 com as mesmas 190 t. Sendo x as toneladas recicladas: 500x + 10 000(190 − x) ≤ 570 000, ou seja, 1 900 000 − 9 500x ≤ 570 000, de onde vem x ≥ 140. O mínimo é 140 toneladas (B).'),
    -- 2º Dia, 160. Gabarito: B.
    ('2º Dia', 'c2462e10e962b2bab4f4176000f45da1f1589d14a74fbc759f8063f40243452d', 'Os cargos são distintos, então a ordem importa. Para presidente há 20 pessoas possíveis. Para secretário restam 18, pois saem o presidente e seu cônjuge. Para tesoureiro restam 16, pois saem também o secretário e seu cônjuge. O total é 20 × 18 × 16 (B). A alternativa 20 × 19 × 18 (C) ignora a restrição dos casais, e 10 × 9 × 8 (A) escolhe só os casais, sem escolher qual pessoa de cada um ocupa o cargo.'),
    -- 2º Dia, 162. Gabarito: C.
    ('2º Dia', '922dc8f3dcab797021c46b3d281f263d1bd8f6ee71a464785ea71afff64e37e5', '“T era 1,59 vezes F” significa T = 1,59 · F, ou seja, a razão entre as concentrações é T/F = 1,59 (C). A relação é multiplicativa, e não aditiva (A, B); a razão F/T valeria 1/1,59 (D); e o produto F · T não tem esse significado (E).'),
    -- 2º Dia, 163. Gabarito: C.
    ('2º Dia', '45e535af34e2631e6671429ca825f652202f377bc3c1e1d10a9d3e01d25afb7c', 'Com o aumento de 20%, o seguro passa a 36 × 1,20 = R$ 43,20 por veículo. As despesas mensais ficam 14 240 + 120 × 43,20 = 14 240 + 5 184 = R$ 19 424,00. Para lucrar R$ 10 000,00, é preciso arrecadar 19 424 + 10 000 = R$ 29 424,00, e a mensalidade de cada uma das 120 vagas será 29 424 ÷ 120 = R$ 245,20 (C).'),
    -- 2º Dia, 164. Gabarito: D.
    ('2º Dia', '27437ab1acd9f3a5e82ee13476ced322da39142c686ca38c7b985fe1fd9d7243', 'Como 1 cm³ = 1 mL, o pote tem 20 000 mL de sorvete. O número de taças é 20 000 ÷ 250 = 80 (D).'),
    -- 2º Dia, 168. Gabarito: E.
    ('2º Dia', '3d33408e3076c8479ad2e98cb3c19e9f62d954fb16329136e86118aefb12bf41', 'A maior torta tem raio de 16 cm, ou seja, 32 cm de diâmetro. Com folga de pelo menos 1 cm de cada lado, a aresta da base precisa ter no mínimo 32 + 1 + 1 = 34 cm; a altura de 7 cm das caixas originais já atende à torta de 6 cm com 1 cm de folga superior. A nova aresta deve ser 34 − 14 = 20 cm maior que a original (E). O valor 18 (D) desconsidera a folga lateral.'),
    -- 2º Dia, 169. Gabarito: A.
    ('2º Dia', 'fb2a9260d90c42473ec072a9de4b28cec1365cfed2a80a742c6ded8321d826ea', 'Para 0 ≤ t ≤ 10, o argumento do logaritmo é K(t + 1)(19 − t), e o produto (t + 1)(19 − t) é uma parábola voltada para baixo, de raízes −1 e 19, com máximo no ponto médio t = 9, que está dentro do intervalo de uso: (9 + 1)(19 − 9) = 100. A pressão é máxima nesse instante, e a recomendação exige 4 · log(100K) ≤ 10, isto é, log(100K) ≤ 2,5, ou 100K ≤ 10^2,5. Logo K ≤ 10^0,5 (A). A alternativa D, 10^2,5/99, resulta de verificar só o fim do intervalo (t = 10), onde o produto vale 99.'),
    -- 2º Dia, 173. Gabarito: C.
    ('2º Dia', '2da19da538f7d8ad98fe74a9790b472c9620757c17347a45c23eadd0da599ddd', 'O filho mais velho recebe a bicicleta ou o celular, mas não os dois: são 2 casos simétricos. Se ele recebe a bicicleta (e não o celular), escolhe os outros 2 presentes entre os 6 que não são nem bicicleta nem celular: C(6,2) = 15. Dos 5 presentes restantes, o mais novo recebe 3, C(5,3) = 10 maneiras, e o do meio fica com os 2 que sobram. Esse caso tem 15 × 10 = 150 distribuições, e o total é 2 × 150 = 300 (C).'),
    -- 2º Dia, 174. Gabarito: C.
    ('2º Dia', '0eaf4a2aed987c9791ef8ca2e56f195c2e05c2245e0a51b836a03ac5d0ff7305', 'O jogador entrou no início do segundo tempo e percorreu 4,5 km em 45 minutos. Mantendo a mesma velocidade média nos 30 minutos de prorrogação, percorreu 4,5 × 30/45 = 3,0 km. O total foi 4,5 + 3,0 = 7,5 km (C).'),
    -- 2º Dia, 176. Gabarito: E.
    ('2º Dia', 'f9762244fdbd4de4a231e68c960596b1d8741460febf1581fbe558ba4252ded0', 'João vence quando seu número é maior ou igual ao maior número de Artur. Se João tira j, a chance de os dois dados de Artur serem ambos ≤ j é (j/6)². Então P(João vence) = (1/6) · (1² + 2² + 3² + 4² + 5² + 6²)/36 = (1/6) · 91/36 = 91/216. A probabilidade de vitória de Artur é 1 − 91/216 = 125/216, cerca de 58%, maior que a de João. O favorito é Artur, com 125/216 (E). A alternativa D traz a probabilidade correta de João, mas ele não é o favorito.'),
    -- 2º Dia, 177. Gabarito: A.
    ('2º Dia', 'e6852a61de8eeaf537106d1564e5ed6da5d06aacacfa11b582a529aba1a177ff', 'A luminância é a razão entre a intensidade luminosa, em candela, e o quadrado da distância, em metro. Sua unidade é, portanto, cd/m² (A). As demais alternativas invertem a razão (B, D, E) ou não elevam a distância ao quadrado (C).');

UPDATE question q
    JOIN entrance_exam e ON e.id = q.entrance_exam_id
    JOIN institution i ON i.id = e.institution_id
    JOIN enem_2025_explanation x ON x.stage = e.stage
                                AND x.statement_sha256 = SHA2(q.statement, 256)
SET q.explanation = x.explanation
WHERE i.acronym = 'INEP'
  AND e.name = 'ENEM'
  AND e.year = 2025
  AND (q.explanation IS NULL OR TRIM(q.explanation) = '');

DROP TEMPORARY TABLE enem_2025_explanation;
